class _ImagesProxy:
    """Proxy for images tools."""

    def delete(self, name: str, *, remove_frame: bool | None = None) -> dict[str, Any]:
        """Delete an image from the document.

        Args:
            name (required): Name of the image to delete (from image_list).
            remove_frame (optional): Also remove the containing frame (default: true).
        """
        return _rpc_call("image_delete", name=name, remove_frame=remove_frame)

    def download(self, url: str, *, verify_ssl: bool | None = None, force: bool | None = None) -> dict[str, Any]:
        """Download an image from URL to local cache. Returns local path for image_insert/image_replace.

        Args:
            url (required): URL of the image to download.
            verify_ssl (optional): Verify SSL certificates (default: false).
            force (optional): Force re-download even if cached (default: false).
        """
        return _rpc_call("image_download", url=url, verify_ssl=verify_ssl, force=force)

    def generate(self, prompt: str, *, source_image: str | None = None, strength: float = 0.75, aspect_ratio: str = 'square', base_size: int = 1024, width: int | None = None, height: int | None = None, provider: str | None = None, image_model: str | None = None) -> dict[str, Any]:
        """Generate an image from a text prompt and insert it. To edit an existing image, pass source_image='selection' (or omit it while a graphic is selected).

        Args:
            prompt (required): Descriptive prompt for image generation or editing.
            source_image (optional): Optional. Use 'selection' to edit the currently selected image (Img2Img). Omit while a graphic is selected to edit in place; omit with no selection to create a new image.
            strength (optional): For editing: how much to change the image (0.0-1.0). Ignored when generating new.
            aspect_ratio (optional): One of: square, landscape_16_9, portrait_9_16, landscape_3_2, portrait_2_3, 1:1, 4:3, 3:4, 16:9, 9:16.
            base_size (optional): Generate resolution in pixels (default 1024). On-page display is capped independently (~135mm longer edge).
            width (optional): Override calculated width.
            height (optional): Override calculated height.
            provider (optional): Override default provider.
            image_model (optional): Override Settings image model for this request (endpoint / OpenRouter).
        """
        return _rpc_call("image_generate", prompt=prompt, source_image=source_image, strength=strength, aspect_ratio=aspect_ratio, base_size=base_size, width=width, height=height, provider=provider, image_model=image_model)

    def get_info(self, name: str) -> dict[str, Any]:
        """Get detailed info about a specific image: URL, dimensions, anchor type, orientation, crop (crop_mm, mm trimmed per edge), and paragraph index.

        Args:
            name (required): Name of the image (from image_list).
        """
        return _rpc_call("image_get_info", name=name)

    def insert(self, path: str, *, locator: str | None = None, paragraph: int | None = None, page: int | None = None, x_mm: float | None = None, y_mm: float | None = None, width_mm: int | None = None, height_mm: int | None = None, target: str | None = None, style: str | None = None, auto_height: bool | None = None) -> dict[str, Any]:
        """Insert an image from local path or URL into the document. URLs are auto-downloaded first. For Writer letterheads, pass target='header' or 'footer' (optionally style) to insert into the page header/footer with auto-height so the logo does not overlap the body. A different-first-page letterhead logo needs first_is_shared=false on the page style (page_set_style_properties) so HeaderTextFirst is its own text object, then target='header_first' (or footer_first) — otherwise the image lands in the shared header and repeats on every page. On Draw/Impress, optional page (0-based) and x_mm/y_mm place the image; omitted x/y centers it. Sizes and positions are millimetres (not 1/100 mm).

        Args:
            path (required): Local file path or URL of the image to insert.
            locator (optional): Unified locator for insertion point (e.g. 'bookmark:NAME', 'heading_text:Title').
            paragraph (optional): Paragraph index for insertion point.
            page (optional): Draw/Impress: 0-based page index (active page if omitted).
            x_mm (optional): Draw/Impress: X position in millimetres (default: centered).
            y_mm (optional): Draw/Impress: Y position in millimetres (default: centered).
            width_mm (optional): Width in millimetres (default: 80).
            height_mm (optional): Height in millimetres (default: 80).
            target (optional): Writer insertion target (default: body). header/footer write the shared page-style region. header_first/footer_first write the first-page letterhead (set first_is_shared=false first, or the first page still shares HeaderText). One of: body, header, footer, header_first, footer_first.
            style (optional): Page style for header/footer target (default: Standard).
            auto_height (optional): When target is a header/footer region, grow the region with the image (default: true) so a taller logo does not overlap the body. Set false to keep a fixed header/footer height.
        """
        return _rpc_call("image_insert", path=path, locator=locator, paragraph=paragraph, page=page, x_mm=x_mm, y_mm=y_mm, width_mm=width_mm, height_mm=height_mm, target=target, style=style, auto_height=auto_height)

    def list(self) -> dict[str, Any]:
        """List all images/graphic objects in the document with name, dimensions, title, and description."""
        return _rpc_call("image_list")

    def list_nearby_files(self, *, filter: str | None = None) -> dict[str, Any]:
        """List image files (.png, .jpg, .jpeg, .gif, .webp, .bmp, .svg) in the same folder as the active document (newest first). Excludes the active file. Use returned path with image_insert or image_replace. Optional filter is a case-insensitive substring on the basename.

        Args:
            filter (optional): Optional basename substring (e.g. 'logo').
        """
        return _rpc_call("image_list_nearby_files", filter=filter)

    def replace(self, name: str, path: str, *, width_mm: float | None = None, height_mm: float | None = None) -> dict[str, Any]:
        """Replace an image's source file keeping position and frame.

        Args:
            name (required): Name of the image to replace (from image_list).
            path (required): Local file path or URL of the replacement image.
            width_mm (optional): Optionally update width in millimetres.
            height_mm (optional): Optionally update height in millimetres.
        """
        return _rpc_call("image_replace", name=name, path=path, width_mm=width_mm, height_mm=height_mm)

    def set_properties(self, name: str, *, width_mm: float | None = None, height_mm: float | None = None, title: str | None = None, description: str | None = None, anchor_type: int | None = None, hori_orient: str | None = None, vert_orient: str | None = None, crop_top_mm: float | None = None, crop_bottom_mm: float | None = None, crop_left_mm: float | None = None, crop_right_mm: float | None = None) -> dict[str, Any]:
        """Resize, reposition, crop, or update caption/alt-text for an image. Crop trims the given millimetres off each edge (crop_*_mm); only the edges you pass change.

        Args:
            name (required): Name of the image (from image_list).
            width_mm (optional): New width in millimetres.
            height_mm (optional): New height in millimetres.
            title (optional): Image title (tooltip text).
            description (optional): Image alternative text (alt-text).
            anchor_type (optional): Anchor type: 0=AT_PARAGRAPH, 1=AS_CHARACTER, 2=AT_PAGE, 3=AT_FRAME, 4=AT_CHARACTER.
            hori_orient (optional): Horizontal position: 'left', 'center', or 'right'. (A raw UNO HoriOrientation integer is also accepted.).
            vert_orient (optional): Vertical position: 'top', 'center', or 'bottom'. (A raw UNO VertOrientation integer is also accepted.).
            crop_top_mm (optional): Millimetres to crop off the TOP edge (0 = no crop). Only edges you pass change.
            crop_bottom_mm (optional): Millimetres to crop off the BOTTOM edge.
            crop_left_mm (optional): Millimetres to crop off the LEFT edge.
            crop_right_mm (optional): Millimetres to crop off the RIGHT edge.
        """
        return _rpc_call("image_set_properties", name=name, width_mm=width_mm, height_mm=height_mm, title=title, description=description, anchor_type=anchor_type, hori_orient=hori_orient, vert_orient=vert_orient, crop_top_mm=crop_top_mm, crop_bottom_mm=crop_bottom_mm, crop_left_mm=crop_left_mm, crop_right_mm=crop_right_mm)

images = _ImagesProxy()


class _IndexProxy:
    """Proxy for index tools."""

    def add_mark(self, text: str, *, kind: str | None = None, primary_key: str | None = None, secondary_key: str | None = None, identifier: str | None = None, author: str | None = None, title: str | None = None, year: Any | None = None, pages: str | None = None, bibliographic_type: Any | None = None, fields: dict[str, Any] | None = None, target: str | None = None, old_content: str | None = None) -> dict[str, Any]:
        """Insert an index mark or a bibliography cite at target. kind=alphabetical|user creates DocumentIndexMark / UserIndexMark (primary_key/secondary_key). kind=bibliography creates TextField.Bibliography — not an index mark; set Identifier/Author/Title/Year/Pages (text defaults to Identifier). primary_key is ignored for cites. After cite changes call indexes_update_all so the bibliography table refreshes. Do not use fields_insert for product cites.

        Args:
            text (required): Index mark entry, or Identifier fallback for kind=bibliography.
            kind (optional): alphabetical/user = index mark; bibliography = TextField.Bibliography cite. One of: alphabetical, user, bibliography.
            primary_key (optional): Alphabetical index primary key. Ignored for bibliography.
            secondary_key (optional): Alphabetical index secondary key. Ignored for bibliography.
            identifier (optional): Cite key (Fields.Identifier). Defaults from text when omitted.
            author (optional): Cite author. Ignored unless kind=bibliography.
            title (optional): Cite title. Ignored unless kind=bibliography.
            year (optional): Cite year (string or integer). Ignored unless kind=bibliography.
            pages (optional): Cite pages / locator. Ignored unless kind=bibliography.
            bibliographic_type (optional): BibliographyDataType name or int (book, article, …). Ignored unless kind=bibliography.
            fields (optional): Extra/override Fields names (Identifier, Author, ISBN, …). Ignored unless kind=bibliography.
            target (optional): Where to insert the mark or cite. One of: beginning, end, selection, full_document, search.
            old_content (optional): Text to find and replace if target = 'search'.
        """
        return _rpc_call("indexes_add_mark", text=text, kind=kind, primary_key=primary_key, secondary_key=secondary_key, identifier=identifier, author=author, title=title, year=year, pages=pages, bibliographic_type=bibliographic_type, fields=fields, target=target, old_content=old_content)

    def create(self, kind: str, *, title: str | None = None, create_from_outline: bool | None = None, target: str | None = None, old_content: str | None = None) -> dict[str, Any]:
        """Create a document index (toc, alphabetical, user, illustration, table, object, bibliography). kind=bibliography inserts the reference table (com.sun.star.text.Bibliography); cites must already exist or be added with indexes_add_mark kind=bibliography, then indexes_update_all. Use target='beginning', 'end', or 'selection'. Use target='search' with old_content to find and replace text.

        Args:
            kind (required): The type of index to create. One of: toc, alphabetical, user, illustration, table, object, bibliography.
            title (optional): The title for the index (e.g., 'Table of Contents').
            create_from_outline (optional): Whether to create the index from the document outline (mainly for toc). Default true.
            target (optional): Where to insert the index. One of: beginning, end, selection, full_document, search.
            old_content (optional): Text to find and replace if target = 'search'.
        """
        return _rpc_call("indexes_create", kind=kind, title=title, create_from_outline=create_from_outline, target=target, old_content=old_content)

    def delete_toc_entry(self, old_content: str, *, index: int | None = None, occurrence: int | None = None, dry_run: bool | None = None) -> dict[str, Any]:
        """Delete one table-of-contents entry (the whole paragraph). Identify it the same way as indexes_refresh_toc_entry: old_content matched inside the TOC only, plus optional index and occurrence. Does not call index update(), so neighboring entries, tabs, and direct formatting stay. indexes_update_all is the full rebuild and drops customized TOC formatting. The agent decides which row is obsolete; this tool does not compare the outline.

        Args:
            old_content (required): Plain text to find inside the TOC entry to delete.
            index (optional): Document index position from indexes_list. Omit when the document has exactly one TOC.
            occurrence (optional): 0-based match inside the TOC only. Omit for the first. Body text with the same words is not a match.
            dry_run (optional): Do not edit. Report text (the entry that would be removed) and an empty text_after.
        """
        return _rpc_call("indexes_delete_toc_entry", old_content=old_content, index=index, occurrence=occurrence, dry_run=dry_run)

    def insert_toc_entry(self, content: str, *, page: str | None = None, hyperlink_url: str | None = None, position: str | None = None, old_content: str | None = None, level: int | None = None, index: int | None = None, occurrence: int | None = None, dry_run: bool | None = None) -> dict[str, Any]:
        """Insert one new row into an existing table of contents. Does not call index update(), and does not modify neighboring entries. Clones the sibling row's Contents N paragraph style, direct character formatting, and tab stops. Set hyperlink_url to an outline target (#…|outline). Page numbers follow the sibling row: plain text after a tab (generated TOC rows store digits in the entry, not a page field). Pass page to set that text; omit it to copy the sibling's page text. position is before, after (both need old_content), or end (after the last TOC entry). indexes_update_all is the full rebuild and drops customized TOC formatting. The agent decides what is missing; this tool does not sync the outline.

        Args:
            content (required): Plain text of the new entry title. May be the full line (Title followed by a tab and the page) when page is omitted.
            page (optional): Plain page text written after a tab. Omit to copy the sibling row's page text. Not a page-number field.
            hyperlink_url (optional): Outline target (#…|outline) for the new row only. Omit to leave the new row unlinked.
            position (optional): Where to insert the one row. before/after need old_content. end appends after the last TOC entry. Default end. One of: before, after, end.
            old_content (optional): Plain text of the existing TOC entry to insert before or after. Not used when position is end.
            level (optional): Contents N paragraph style (1-10). Omit to clone the sibling entry's style.
            index (optional): Document index position from indexes_list. Omit when the document has exactly one TOC.
            occurrence (optional): 0-based match inside the TOC only, when position is before or after. Omit for the first.
            dry_run (optional): Do not edit. Report text (the sibling entry) and text_after (the row that would be inserted).
        """
        return _rpc_call("indexes_insert_toc_entry", content=content, page=page, hyperlink_url=hyperlink_url, position=position, old_content=old_content, level=level, index=index, occurrence=occurrence, dry_run=dry_run)

    def list(self) -> dict[str, Any]:
        """List document indexes (TOC, alphabetical, user, bibliography tables). type matches indexes_create kind (bibliography via getServiceName). For in-flow cites use indexes_list_cites, not this tool."""
        return _rpc_call("indexes_list")

    def list_cites(self) -> dict[str, Any]:
        """List native bibliography cite fields (TextField.Bibliography). Returns identifier, key Fields (Author, Title, Year, Pages, type), and location. Does not list the bibliography table — use indexes_list for that."""
        return _rpc_call("indexes_list_cites")

    def refresh_toc_entry(self, old_content: str, content: str, *, hyperlink_url: str | None = None, index: int | None = None, occurrence: int | None = None, dry_run: bool | None = None) -> dict[str, Any]:
        """Replace one substring inside a single table-of-contents entry and, when that text sits in one outline hyperlink (#…|outline), update that URL. Does not call index update(), so other entries, tabs, page numbers, and direct formatting stay. Page numbers are left as they are. indexes_update_all is the full rebuild and drops customized TOC formatting. Pass hyperlink_url to set the outline target, including when content equals old_content. Bookmark targets are not rewritten. To add or remove one row, use indexes_insert_toc_entry or indexes_delete_toc_entry.

        Args:
            old_content (required): Substring to find inside the TOC entry.
            content (required): Plain text to write in its place. May equal old_content when only hyperlink_url should change.
            hyperlink_url (optional): Exact outline URL (#…|outline) when the match overlaps exactly one outline link. Omit to substitute old_content once outside the |outline suffix.
            index (optional): Document index position from indexes_list. Omit when the document has exactly one TOC.
            occurrence (optional): 0-based match inside the TOC only. Omit for the first. Body text with the same words is not a match.
            dry_run (optional): Do not edit. Report text (the entry before) and text_after, plus the outline URL before and after when the match is one |outline link.
        """
        return _rpc_call("indexes_refresh_toc_entry", old_content=old_content, content=content, hyperlink_url=hyperlink_url, index=index, occurrence=occurrence, dry_run=dry_run)

    def update_all(self) -> dict[str, Any]:
        """Refresh all document indexes (TOC, alphabetical, bibliography table). Call after inserting or editing bibliography cites so the reference list updates. A TOC refresh rebuilds every entry and drops customized direct formatting. To change one entry without that rebuild, use indexes_refresh_toc_entry, indexes_insert_toc_entry, or indexes_delete_toc_entry. Those tools do not call update() and do not recalculate page numbers."""
        return _rpc_call("indexes_update_all")

index = _IndexProxy()


